package invitation

import "time"

// InvitationCode 表示用户固定的邀请码，1:1 映射用户。
type InvitationCode struct {
	ID        uint
	UserID    uint
	Code      string
	CreatedAt time.Time
	UpdatedAt time.Time
}

// Relationship 表示一次邀请事件及其双方奖励发放状态。
type Relationship struct {
	ID                   uint
	InviterUserID        uint
	InvitedUserID        uint
	InvitationCode       string
	InviteeRewardNanousd int64
	InviterRewardNanousd int64
	InviteeRewardedAt    *time.Time
	InviterRewardedAt    *time.Time
	CreatedAt            time.Time
	UpdatedAt            time.Time
}

// InvitationPanel 表示用户中心的邀请面板视图。
type InvitationPanel struct {
	InvitationCode string
	InviteLink     string
	InviteCount    int64
}

// InvitedUser 表示邀请人视角下被邀请人的脱敏信息。
type InvitedUser struct {
	RelationshipID     uint
	InvitedUserID      uint
	InvitedDisplayName string
	InvitedUsername    string
	InvitedAt          time.Time
	InviterRewardNanousd int64
}

