// backfillUsageLedgerBillingAt 为历史用量账单补齐 billing_at 字段。
func backfillUsageLedgerBillingAt(db *gorm.DB) error {
	if !db.Migrator().HasTable(&model.UsageLedger{}) || !db.Migrator().HasColumn(&model.UsageLedger{}, "billing_at") {
		return nil
	}
