func (s *Service) buildInviteLink(code string) string {
	base := ""
	if s.cfg != nil {
		base = s.cfg.Snapshot().PublicWebBaseURL
	}
	base = strings.TrimRight(strings.TrimSpace(base), "/")
	// 项目只有 /login 路由（注册是其 mode），邀请链接指向 /login?invite= 并带 mode=register，
