+				}
+				if createErr := db.Create(&model.InvitationCode{UserID: userID, Code: code}).Error; createErr != nil {
+					return createErr
+				}
+			}
+		}
+		if len(userIDs) < batchSize {
+			return nil
+		}
+	}
+}
