}

func (r *Repo) SetKeywordRuleEnabled(ctx context.Context, id uint, enabled bool) error {
	result := r.db.WithContext(ctx).Model(&model.WeChatKeywordRule{}).Where("id = ?", id).Update("enabled", enabled)
